Test("a valid signup has no errors", () =>
    Eq(Validate(new SignupDto("ana@example.com", "Ana", 30, new[] { "reader" })).Count, 0));

Test("every problem is reported, keyed by field", () =>
{
    var errors = Validate(new SignupDto(" ", "Ana", 9, new[] { "admin" }));
    Eq(errors.Keys.OrderBy(k => k, StringComparer.Ordinal).ToList(), new[] { "Age", "Email", "Roles" });
    Eq(errors["Email"], new[] { "Email is required." });
    Eq(errors["Age"], new[] { "Age must be between 13 and 120." });
    Eq(errors["Roles"], new[] { "Unknown role 'admin'." });
});

Test("email format and name length", () =>
{
    var errors = Validate(new SignupDto("ana@@x", new string('n', 51), null, null));
    Eq(errors["Email"], new[] { "Email is not a valid address." });
    Eq(errors["Name"], new[] { "Name must be at most 50 characters." });
});

Test("several bad roles add several messages", () =>
    Eq(Validate(new SignupDto("a@b.io", "Ana", null, new[] { "writer", "root", "Reader" }))["Roles"], new[] { "Unknown role 'root'.", "Unknown role 'Reader'." }));

Test("optional fields may be missing; edges are inclusive (boundary)", () =>
{
    Eq(Validate(new SignupDto("a@b.io", "Ana", null, null)).Count, 0);
    Eq(Validate(new SignupDto("a@b.io", "Ana", 13, null)).Count, 0);
    Eq(Validate(new SignupDto("a@b.io", new string('n', 50), 120, null)).Count, 0);
    Ok(Validate(new SignupDto(null, null, null, null)).ContainsKey("Name"), "a null name is required");
});

