// ─────────────────────────────────────────────────────────────────────────
//  01 · validate a signup★★☆ core
//  concepts: validation · ValidationProblemDetails errors
// ─────────────────────────────────────────────────────────────────────────
//
//  Every failed rule, keyed by field, in one response.

using static Bootcamp.Check;

Dictionary<string, string[]> Validate(SignupDto dto)
{
    var errors = new Dictionary<string, List<string>>();
    void Add(string field, string message)
    {
        if (!errors.TryGetValue(field, out var list)) errors[field] = list = new List<string>();
        list.Add(message);
    }
    if (string.IsNullOrWhiteSpace(dto.Email)) Add("Email", "Email is required.");
    else
    {
        var parts = dto.Email.Trim().Split('@');
        if (parts.Length != 2 || parts[0].Length == 0 || parts[1].Length == 0) Add("Email", "Email is not a valid address.");
    }
    if (string.IsNullOrWhiteSpace(dto.Name)) Add("Name", "Name is required.");
    else if (dto.Name.Trim().Length > 50) Add("Name", "Name must be at most 50 characters.");
    if (dto.Age is { } age && (age < 13 || age > 120)) Add("Age", "Age must be between 13 and 120.");
    foreach (var role in dto.Roles ?? Array.Empty<string>())
        if (role is not ("reader" or "writer")) Add("Roles", $"Unknown role '{role}'.");
    return errors.ToDictionary(e => e.Key, e => e.Value.ToArray());
}

